mapper.select:
SELECT FROM t_session_product sp INNER JOIN t_session s ON sp.session_id = s.id AND s.is_deleted = 0 AND s.session_status = 1 INNER JOIN t_consign_goods g ON sp.goods_id = g.id AND g.is_deleted = 0 AND g.online_status = 1 AND g.goods_status = 1 WHERE sp.is_deleted = 0 AND sp.stock > 0
AND sp.session_id = #{sessionId}
ORDER BY s.sort ASC, sp.sort ASC, sp.id DESC
